DELETE FROM region WHERE rowid IN (SELECT rowid FROM region WHERE r_regionkey = (SELECT region_base FROM q2_test_keys) QUALIFY row_number() OVER (PARTITION BY r_regionkey ORDER BY rowid) > 1);
DELETE FROM nation WHERE rowid IN (SELECT rowid FROM nation WHERE n_nationkey = (SELECT nation_base FROM q2_test_keys) QUALIFY row_number() OVER (PARTITION BY n_nationkey ORDER BY rowid) > 1);
DELETE FROM supplier WHERE rowid IN (SELECT rowid FROM supplier WHERE s_suppkey = (SELECT supp_base FROM q2_test_keys) QUALIFY row_number() OVER (PARTITION BY s_suppkey ORDER BY rowid) > 1);
DELETE FROM part WHERE rowid IN (SELECT rowid FROM part WHERE p_partkey = (SELECT part_base + 125 FROM q2_test_keys) QUALIFY row_number() OVER (PARTITION BY p_partkey ORDER BY rowid) > 1);
DELETE FROM partsupp WHERE rowid IN (SELECT rowid FROM partsupp WHERE ps_partkey = (SELECT part_base + 125 FROM q2_test_keys) AND ps_suppkey = (SELECT supp_base FROM q2_test_keys) QUALIFY row_number() OVER (PARTITION BY ps_partkey, ps_suppkey ORDER BY rowid) > 1);
